#include <cstdio>
#include <cstring>

char s[100005];
int cnt[26];

int main() {
    if (!fgets(s, sizeof(s), stdin)) { printf("-1\n"); return 0; }
    int len = (int)strlen(s);
    while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r')) s[--len] = 0;

    memset(cnt, 0, sizeof(cnt));
    for (int i = 0; i < len; ++i) ++cnt[s[i] - 'a'];   // 第一趟

    int ans = -1;
    for (int i = 0; i < len; ++i) {                    // 第二趟
        if (cnt[s[i] - 'a'] == 1) { ans = i; break; }
    }
    printf("%d\n", ans);
    return 0;
}
